import { useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { ArrowDownToLine, ArrowLeft, ArrowRight, BookOpen, CalendarDays, Check, CheckCheck, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, ClipboardCheck, FilePlus2, FileText, FolderOpen, GraduationCap, LayoutDashboard, LoaderCircle, Menu, Plus, Save, Search, Settings2, ShieldCheck, Sparkles, Trash2, UploadCloud, Users, X, AlertCircle, PencilLine, ExternalLink, RefreshCw } from 'lucide-react';
import { request, json } from './api';
import Materials from './Materials';
import Practice from './Practice';
import Modal from './ModalFrame';
import type { Attachment, Bootstrap, Exam, ExamSummary, Job, Plan, Question, QuestionSource, Settings, Student, Workspace } from './types';

const today=()=>new Date().toLocaleDateString('en-CA');
const date=(value?:string|null)=>value?value.slice(0,10).replaceAll('-','.'): '—';
const score=(value?:number|null)=>value===null||value===undefined?'—':String(value);
const initials=(name:string)=>name.replace(/[（(][^）)]*[）)]/g,'').trim().slice(-2)||'学生';
const statusText={draft:'待录入',review:'待校对',confirmed:'已归档'};
const errorText=(e:unknown)=>e instanceof Error?e.message:'操作未完成，请重试';
const blankQuestion=(number:number):Question=>({id:crypto.randomUUID(),number:String(number),stem:'',student_answer:'',correct_answer:'',school_score:null,max_score:1,ai_score:null,knowledge_tag:'',error_reason:'',teacher_note:'',needs_review:true,reviewed:false,source_page:1,source_attachment_id:null});
type Page='dashboard'|'students'|'student'|'exam'|'materials'|'practice';

function Button({children,icon,variant='',className='',...props}:React.ButtonHTMLAttributes<HTMLButtonElement>&{icon?:ReactNode;variant?:string}){return <button className={`button ${variant} ${className}`} {...props}>{icon}{children}</button>}
function Empty({icon=<FolderOpen size={28}/>,title,text,children}:{icon?:ReactNode;title:string;text:string;children?:ReactNode}){return <div className="empty"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{text}</p>{children}</div>}
function Field({label,hint,error,children,className=''}:{label:string;hint?:string;error?:string;children:ReactNode;className?:string}){return <label className={`field ${error?'has-error':''} ${className}`}><span>{label}</span>{children}{error?<small className="field-error" role="alert">{error}</small>:hint&&<small>{hint}</small>}</label>}
function Badge({status}:{status:ExamSummary['status']}){return <span className={`badge ${status}`}><span/>{statusText[status]}</span>}
function useProtectedClose(modified:boolean,busy:boolean,label:string,close:()=>void){
 useEffect(()=>{if(!modified)return;const handler=(event:BeforeUnloadEvent)=>{event.preventDefault();event.returnValue=''};window.addEventListener('beforeunload',handler);return()=>window.removeEventListener('beforeunload',handler)},[modified]);
 return ()=>{if(!busy&&(!modified||window.confirm(`${label}还有未保存的内容，放弃修改并关闭吗？`)))close()};
}
type ExamIssue={field:string;message:string};
const numberInput=(value:string)=>value===''?NaN:Number(value);
const visibleNumber=(value:number)=>Number.isFinite(value)?value:'';
function examIssues(exam:Exam):ExamIssue[]{
 const issues:ExamIssue[]=[];
 if(!exam.title.trim())issues.push({field:'exam-title',message:'请填写试卷名称。'});
 if(!/^\d{4}-\d{2}-\d{2}$/.test(exam.exam_date))issues.push({field:'exam-date',message:'请填写有效的考试日期。'});
 if(!Number.isFinite(exam.full_score)||exam.full_score<=0)issues.push({field:'exam-full-score',message:'试卷满分必须大于 0。'});
 if(exam.school_score!==null&&(!Number.isFinite(exam.school_score)||exam.school_score<0||exam.school_score>exam.full_score))issues.push({field:'exam-school-score',message:'总分须在 0 与试卷满分之间。'});
 for(const q of exam.questions){
  if(!q.number.trim())issues.push({field:`question-${q.id}-number`,message:'请填写题号。'});
  if(!Number.isFinite(q.max_score)||q.max_score<=0)issues.push({field:`question-${q.id}-max`,message:'本题满分必须大于 0。'});
  if(q.school_score!==null&&(!Number.isFinite(q.school_score)||q.school_score<0||q.school_score>q.max_score))issues.push({field:`question-${q.id}-score`,message:`第 ${q.number||'未编号'} 题得分须在 0 与本题满分之间。`});
 }
 return issues;
}
function focusField(id:string){requestAnimationFrame(()=>requestAnimationFrame(()=>{const element=document.getElementById(id);element?.scrollIntoView({block:'center',behavior:'auto'});element?.focus({preventScroll:true})}))}

export default function App(){
 const [workspace,setWorkspace]=useState<Workspace>(()=>localStorage.getItem('teacher-workspace')==='personal'?'personal':'demo');
 const ws=useRef(workspace); ws.current=workspace;
 const [data,setData]=useState<Bootstrap|null>(null),[page,setPage]=useState<Page>('dashboard'),[student,setStudent]=useState<Student|null>(null),[exam,setExam]=useState<Exam|null>(null);
 const [loading,setLoading]=useState(true),[error,setError]=useState(''),[toast,setToast]=useState(''),[search,setSearch]=useState(''),[busy,setBusy]=useState(''),[job,setJob]=useState<Job|null>(null),[dirty,setDirty]=useState(false);
 const [validationTarget,setValidationTarget]=useState<ExamIssue|null>(null);
 const [studentModal,setStudentModal]=useState(false),[examModal,setExamModal]=useState(false),[settingsModal,setSettingsModal]=useState(false),[editingPlan,setEditingPlan]=useState<Plan|null>(null),[manualPlan,setManualPlan]=useState(false),[mobileNav,setMobileNav]=useState(false);
 const generation=useRef(0);const moduleGuard=useRef<(()=>boolean)|null>(null);const [moduleEpoch,setModuleEpoch]=useState(0);
 useEffect(()=>{window.scrollTo(0,0)},[page,workspace,student?.id,exam?.id]);
 const api=<T,>(path:string,options?:RequestInit)=>request<T>(workspace,path,options);
 const notify=(text:string)=>setToast(text);
 async function loadBootstrap(silent=false){const at=workspace;if(!silent)setLoading(true);try{const result=await request<Bootstrap>(at,'/bootstrap');if(ws.current!==at)return;setData(result);setError('')}catch(e){if(ws.current===at)setError(errorText(e))}finally{if(ws.current===at&&!silent)setLoading(false)}}
 useEffect(()=>{generation.current++;setData(null);setStudent(null);setExam(null);setPage('dashboard');setDirty(false);setValidationTarget(null);setJob(null);setBusy('');setError('');setSearch('');setMobileNav(false);setStudentModal(false);setExamModal(false);setSettingsModal(false);setEditingPlan(null);setManualPlan(false);localStorage.setItem('teacher-workspace',workspace);void loadBootstrap()},[workspace]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),5000);return()=>clearTimeout(timer)},[toast]);
 useEffect(()=>{if(!dirty)return;const onLeave=(event:BeforeUnloadEvent)=>{event.preventDefault();event.returnValue=''};window.addEventListener('beforeunload',onLeave);return()=>window.removeEventListener('beforeunload',onLeave)},[dirty]);
 const canLeave=()=>{if(moduleGuard.current&&!moduleGuard.current())return false;if(busy&&busy!=='navigate'){notify('当前操作正在进行，请完成后再切换页面或空间。');return false}return !dirty||window.confirm('试卷还有未保存的修改，确定离开吗？')};
 function navigate(next:Page){if(!canLeave())return;setBusy('');setModuleEpoch(value=>value+1);generation.current++;setDirty(false);setValidationTarget(null);setPage(next);setMobileNav(false);setError('')}
 function changeWorkspace(next:Workspace){if(next===workspace||!canLeave())return;setWorkspace(next)}
 async function openStudent(id:string){if(!canLeave())return;const at=workspace,token=++generation.current;setBusy('navigate');setError('');try{const s=await api<Student>(`/students/${id}`);if(ws.current!==at||token!==generation.current)return;setStudent(s);setPage('student');setDirty(false);setValidationTarget(null)}catch(e){if(token===generation.current)setError(errorText(e))}finally{if(ws.current===at&&token===generation.current)setBusy('')}}
 async function openExam(id:string){if(!canLeave())return;const at=workspace,token=++generation.current;setBusy('navigate');setError('');try{const x=await api<Exam>(`/exams/${id}`);if(ws.current!==at||token!==generation.current)return;const s=await api<Student>(`/students/${x.student_id}`);if(ws.current!==at||token!==generation.current)return;setExam(x);setStudent(s);setPage('exam');setDirty(false);setValidationTarget(null)}catch(e){if(ws.current===at&&token===generation.current)setError(errorText(e))}finally{if(ws.current===at&&token===generation.current)setBusy('')}}
 async function refreshStudent(){if(!student)return;const at=workspace;const s=await api<Student>(`/students/${student.id}`);if(ws.current===at)setStudent(s)}
 async function saveExam():Promise<Exam|null>{if(!exam||busy)return null;const issue=examIssues(exam)[0];if(issue){setValidationTarget({...issue});return null}const at=workspace;setBusy('save');setError('');setValidationTarget(null);try{const saved=await api<Exam>(`/exams/${exam.id}`,json('PUT',{revision:exam.revision,title:exam.title,exam_date:exam.exam_date,kind:exam.kind,full_score:exam.full_score,school_score:exam.school_score,notes:exam.notes,questions:exam.questions}));if(ws.current!==at)return null;setExam(saved);setDirty(false);notify('试卷修改已保存');void loadBootstrap(true);return saved}catch(e){if(ws.current===at)setError(errorText(e));return null}finally{if(ws.current===at)setBusy('')}}
 async function confirmExam(){if(!exam||busy)return;if(exam.school_score===null){setValidationTarget({field:'exam-school-score',message:exam.kind==='school'?'学校卷归档前，请填写原卷总分。':'练习归档前，请填写老师确认总分。'});return}const issue=examIssues(exam)[0];if(issue){setValidationTarget({...issue});return}setError('');const at=workspace;const current=dirty?await saveExam():exam;if(!current)return;setBusy('confirm');try{const saved=await api<Exam>(`/exams/${current.id}/confirm`,json('POST',{revision:current.revision}));if(ws.current!==at)return;setExam(saved);setDirty(false);notify('已确认归档，学生档案已更新');try{await refreshStudent()}catch{notify('试卷已归档；学生档案刷新未完成，重新打开档案即可。')}void loadBootstrap(true)}catch(e){if(ws.current===at)setError(errorText(e))}finally{if(ws.current===at)setBusy('')}}
 async function uploadAttachments(files:FileList|File[]){if(!exam||!files.length)return;const at=workspace;const current=dirty?await saveExam():exam;if(!current)return;const form=new FormData();Array.from(files).forEach(f=>form.append('files',f));setBusy('upload');setError('');try{const saved=await api<Exam>(`/exams/${current.id}/attachments`,{method:'POST',body:form});if(ws.current!==at)return;setExam(saved);setDirty(false);notify('原件已保存。点击识别后才会发送给所配置的模型。');void loadBootstrap(true)}catch(e){if(ws.current===at)setError(errorText(e))}finally{if(ws.current===at)setBusy('')}}
 async function followJob(first:Job,onDone:()=>Promise<void>){const token=generation.current,at=workspace;setJob(first);let current=first;while(current.status==='queued'||current.status==='running'){await new Promise(resolve=>setTimeout(resolve,1500));if(token!==generation.current||at!==ws.current)return;current=await request<Job>(at,`/jobs/${first.id}`);if(token!==generation.current)return;setJob(current)}if(current.status==='failed')throw new Error(current.message||'模型处理失败，请检查配置后重试');await onDone();setJob(null)}
 async function recognize(){if(!exam||busy||exam.status==='confirmed')return;if(!data?.ai.configured){setSettingsModal(true);return}if(exam.questions.length&&!window.confirm('重新识别成功后，会替换当前全部题目，包括人工填写的答案、得分、错因和备注；已保存的题目也会被替换。需要保留时，请先取消、保存修改并下载备份。确定继续识别吗？'))return;const current=dirty?await saveExam():exam;if(!current)return;const at=workspace;setBusy('recognize');setError('');try{const first=await api<Job>(`/exams/${current.id}/recognize`,json('POST',{}));await followJob(first,async()=>{const saved=await request<Exam>(at,`/exams/${current.id}`);if(ws.current===at){setExam(saved);setDirty(false);notify('识别完成，请对照原卷逐题校对');void loadBootstrap(true)}})}catch(e){if(ws.current===at){setError(errorText(e));setJob(null)}}finally{if(ws.current===at)setBusy('')}}
 async function generatePlan(examId?:string){if(!student)return;if(!data?.ai.configured){setSettingsModal(true);return}const at=workspace,id=student.id;setBusy('plan');setError('');try{const first=await api<Job>(`/students/${id}/plans`,json('POST',examId?{exam_id:examId}:{}));await followJob(first,async()=>{const updated=await request<Student>(at,`/students/${id}`);if(ws.current!==at)return;setStudent(updated);const plans=updated.plans||[];if(plans.length)setEditingPlan([...plans].sort((a,b)=>b.created_at.localeCompare(a.created_at))[0]);notify('教案已生成，授课前请核对并调整');void loadBootstrap(true)})}catch(e){if(ws.current===at){setError(errorText(e));setJob(null)}}finally{if(ws.current===at)setBusy('')}}
 async function downloadBackup(){setBusy('backup');try{const response=await fetch('/api/backup',{headers:{'X-Workspace':workspace}});if(!response.ok)throw new Error('备份下载失败，请重试');const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`英语班主任-${workspace==='demo'?'示例空间':'个人资料库'}-${today()}.zip`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('备份已下载，不包含模型配置或密钥')}catch(e){setError(errorText(e))}finally{setBusy('')}}
 const list=(data?.students||[]).filter(s=>`${s.name} ${s.grade} ${s.school}`.toLowerCase().includes(search.toLowerCase()));
 const title=page==='dashboard'?'工作台':page==='students'?'我的学生':page==='student'?'学生档案':page==='materials'?'教材与真题库':page==='practice'?'针对性练习':'试卷校对';
 return <div className="app-shell">
  {mobileNav&&<div className="sidebar-mask" onClick={()=>setMobileNav(false)}/>}
  <aside className={`sidebar ${mobileNav?'is-open':''}`}><a className="brand" href="#" onClick={e=>{e.preventDefault();navigate('dashboard')}}><div className="brand-icon"><BookOpen size={25}/></div><div><strong>英语班主任</strong><small>TEACHER'S DESK</small></div></a>
   <div className="workspace-switch"><span className="nav-caption">当前空间</span><div className="workspace-buttons"><button className={workspace==='demo'?'active':''} onClick={()=>changeWorkspace('demo')}>示例空间</button><button className={workspace==='personal'?'active':''} onClick={()=>changeWorkspace('personal')}>个人资料库</button></div><p>{workspace==='demo'?'虚构学生 · 可自由体验':'仅记录你的真实教学资料'}</p></div>
   <span className="nav-caption">教学工作</span><nav><button className={page==='dashboard'?'active':''} onClick={()=>navigate('dashboard')}><LayoutDashboard size={20}/>工作台</button><button className={['students','student','exam','practice'].includes(page)?'active':''} onClick={()=>navigate('students')}><Users size={20}/>我的学生<span className="nav-number">{data?.stats.students??'—'}</span></button><button className={page==='materials'?'active':''} onClick={()=>navigate('materials')}><BookOpen size={20}/>教材与真题库</button></nav>
   <div className="sidebar-note"><span className="tiny-line"/><p>每一次错题，<br/>都是下一课的起点。</p><small>观察 · 教学 · 复测</small></div>
   <div className="sidebar-bottom"><button onClick={()=>setSettingsModal(true)}><Settings2 size={19}/>模型设置<span className={`connection-dot ${data?.ai.configured?'on':''}`}/></button><button onClick={downloadBackup} disabled={!!busy}><ArrowDownToLine size={19}/>下载当前空间备份</button><div className="local-label"><ShieldCheck size={14}/>资料保存在本机</div></div>
  </aside>
  <div className="workspace-main"><header className="topbar"><div className="breadcrumbs"><button className="icon-button mobile-menu" aria-label="展开导航" onClick={()=>setMobileNav(true)}><Menu size={23}/></button><span>教学空间</span><ChevronRight size={14}/><strong>{title}</strong></div><div className="topbar-right"><span className={`space-badge ${workspace}`}>{workspace==='demo'?<Sparkles size={14}/>:<ShieldCheck size={14}/>} {workspace==='demo'?'示例空间 · 全部为虚构数据':'个人资料库'}</span><div className="teacher-avatar">师</div></div></header>
   <main>
    {error&&<div role="alert" className="alert error"><AlertCircle size={20}/><span>{error}</span><button className="icon-button" onClick={()=>setError('')} aria-label="关闭错误"><X size={17}/></button></div>}
    {job&&<div role="status" className="alert info"><LoaderCircle size={20} className="spin"/><span>{job.message||'模型正在处理，请稍候…'}。可以保留此页等待，结果不会自动确认为学生事实。</span></div>}
    {loading?<div className="page-loading"><LoaderCircle className="spin" size={30}/><p>正在打开教学空间…</p></div>:!data?<Empty title="暂时无法连接工作台" text="请确认本地服务已启动，再重新连接。"><Button icon={<RefreshCw size={17}/>} onClick={()=>loadBootstrap()}>重新连接</Button></Empty>:<>
     {(page==='dashboard'||page==='students')&&<>
      <div className="page-heading"><div><div className="eyebrow">{page==='dashboard'?'YOUR TEACHING, IN FOCUS':'EVERY STUDENT MATTERS'}</div><h1>{page==='dashboard'?'今天，从了解学生开始。':'每个学生，都有自己的进度。'}</h1><p>{page==='dashboard'?'把试卷中的问题，变成下一堂课的重点。':'保存每次练习的证据，跟进每一次教学后的变化。'}</p></div><Button icon={<Plus size={18}/>} onClick={()=>setStudentModal(true)}>添加学生</Button></div>
      {page==='dashboard'&&<><div className="stat-grid"><Stat title="在册学生" value={data.stats.students} icon={<Users size={21}/>} detail="独立档案，持续跟进"/><Stat title="已归档试卷" value={data.stats.confirmed_exams} icon={<ClipboardCheck size={21}/>} detail="经老师确认的学习证据"/><Stat title="待校对试卷" value={data.stats.pending_exams} icon={<FileText size={21}/>} detail="校对后再进入学生档案" tone="warm"/><Stat title="教学计划" value={data.stats.plans} icon={<BookOpen size={21}/>} detail="教案、课后记录与复测"/></div>
       {!data.ai.configured&&<div className="setup-banner"><div className="setup-symbol"><Sparkles size={22}/></div><div><strong>先手工录入，也能开始教学记录</strong><p>连接模型后可识别试卷、生成教案。原件上传不会自动调用 AI。</p></div><Button variant="secondary" onClick={()=>setSettingsModal(true)} icon={<ArrowRight size={16}/>}>配置模型</Button></div>}
      </>}
      <div className="section-top"><div><h2>我的学生 <span className="count">{data.students.length}</span></h2><p>最近的表现与需要关注的问题</p></div><div className="search-box"><Search size={18}/><input aria-label="搜索学生" placeholder="搜索姓名、年级或学校" value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button aria-label="清除搜索" onClick={()=>setSearch('')}><X size={16}/></button>}</div></div>
      {list.length?<div className="student-grid">{list.map((s,i)=><StudentCard key={s.id} student={s} index={i} demo={workspace==='demo'} open={()=>void openStudent(s.id)}/>)}</div>:<Empty title={search?'没有找到这位学生':'从第一位学生开始'} text={search?'换个关键词试试。':'创建独立档案，再保存试卷和教学记录。个人资料库不会导入示例学生。'}>{!search&&<Button icon={<Plus size={17}/>} onClick={()=>setStudentModal(true)}>添加第一位学生</Button>}</Empty>}
      {page==='dashboard'&&<section className="panel recent-panel"><div className="section-top"><div><h2>试卷收件箱</h2><p>从原卷到教学证据，每一步都由你确认</p></div><span className="subtle">最近 {data.recent_exams.length} 份</span></div>{data.recent_exams.length?<div className="exam-list">{data.recent_exams.map(x=><button className="exam-row" key={x.id} onClick={()=>void openExam(x.id)}><div className={`file-symbol ${x.status==='confirmed'?'complete':''}`}><FileText size={22}/></div><div className="row-main"><strong>{x.title}</strong><span>{data.students.find(s=>s.id===x.student_id)?.name||'学生'} <i>·</i> {date(x.exam_date)} <i>·</i> {x.kind==='school'?'学校试卷':'练习 / 复测'}</span></div><Badge status={x.status}/><ChevronRight size={19}/></button>)}</div>:<div className="quiet-empty">还没有试卷。打开学生档案，添加第一份原卷。</div>}</section>}
     </>}
     {page==='student'&&student&&<StudentDetail student={student} demo={workspace==='demo'} back={()=>navigate('students')} newExam={()=>{if(!busy)setExamModal(true)}} openExam={id=>void openExam(id)} generate={()=>void generatePlan()} manual={()=>{if(!busy)setManualPlan(true)}} editPlan={p=>{if(!busy)setEditingPlan(p)}} openPractice={()=>{if(canLeave()){setDirty(false);setPage('practice')}}} busy={!!busy} configured={data.ai.configured}/>}
     {page==='materials'&&<Materials key={`${workspace}-${moduleEpoch}`} workspace={workspace} configured={data.ai.configured} guardRef={moduleGuard} notify={notify} configure={()=>setSettingsModal(true)}/>}
     {page==='practice'&&student&&<Practice key={`${workspace}-${student.id}`} workspace={workspace} student={student} guardRef={moduleGuard} notify={notify} back={()=>void openStudent(student.id)} openExam={created=>{if(created.student_id!==student.id){setError('试卷与当前学生不一致，已停止跳转');return}generation.current++;setExam(created);setDirty(false);setPage('exam');void loadBootstrap(true)}}/>}
      {page==='exam'&&exam&&student&&<ExamReview key={exam.id} exam={exam} student={student} busy={busy} dirty={dirty} validationTarget={validationTarget} configured={data.ai.configured} back={()=>void openStudent(student.id)} change={next=>{setExam(next);setDirty(true);setValidationTarget(null)}} save={()=>void saveExam()} confirm={()=>void confirmExam()} upload={files=>void uploadAttachments(files)} recognize={()=>void recognize()} generate={()=>void generatePlan(exam.id)} manual={()=>{if(!busy)setManualPlan(true)}} configure={()=>setSettingsModal(true)}/>}
    </>}
    <footer className="workspace-footer"><span>英语班主任</span><span>观察有依据 · 教学有重点 · 进步有记录</span></footer>
   </main>
  </div>
  {toast&&<div className="toast" role="status"><CheckCheck size={20}/><span>{toast}</span><button aria-label="关闭提示" onClick={()=>setToast('')}><X size={16}/></button></div>}
  {studentModal&&<StudentForm demo={workspace==='demo'} close={()=>setStudentModal(false)} submit={async values=>{const at=workspace;const s=await api<Student>('/students',json('POST',values));if(ws.current!==at)return;setStudentModal(false);await loadBootstrap(true);await openStudent(s.id);notify('学生档案已创建')}}/>}
  {examModal&&student&&<ExamForm name={student.name} close={()=>setExamModal(false)} submit={async(values,files)=>{const at=workspace;let x=await api<Exam>(`/students/${student.id}/exams`,json('POST',values));if(files.length){const form=new FormData();files.forEach(f=>form.append('files',f));try{x=await api<Exam>(`/exams/${x.id}/attachments`,{method:'POST',body:form})}catch(e){if(ws.current===at){setError(`试卷已创建，但附件上传未完成：${errorText(e)}。可在校对页重新上传。`)}}}if(ws.current!==at)return;setExam(x);setPage('exam');setExamModal(false);setDirty(false);void loadBootstrap(true);notify('试卷已创建，开始校对吧')}}/>}
  {settingsModal&&<SettingsModal workspace={workspace} close={()=>setSettingsModal(false)} saved={()=>void loadBootstrap(true)}/>}
   {(editingPlan||manualPlan)&&student&&<PlanEditor key={editingPlan?.id||`manual-${student.id}`} plan={editingPlan} student={student} examId={page==='exam'?exam?.id:undefined} close={()=>{setEditingPlan(null);setManualPlan(false)}} save={async values=>{const at=workspace;const saved=editingPlan?await api<Plan>(`/plans/${editingPlan.id}`,json('PATCH',values)):await api<Plan>(`/students/${student.id}/plans/manual`,json('POST',values));if(ws.current!==at)return;setEditingPlan(saved);setManualPlan(false);notify('教案与跟进记录已保存');try{await refreshStudent()}catch{notify('教案已保存；学生档案刷新未完成，重新打开档案即可。')}void loadBootstrap(true)}}/>}
 </div>
}

function Stat({title,value,detail,icon,tone=''}:{title:string;value:number;detail:string;icon:ReactNode;tone?:string}){return <div className={`stat-card ${tone}`}><div><span>{title}</span><div className="stat-value">{value}<small>{title==='在册学生'?'人':'份'}</small></div><p>{detail}</p></div><div className="stat-icon">{icon}</div></div>}
function StudentCard({student:s,index,demo,open}:{student:Student;index:number;demo:boolean;open:()=>void}){return <button className="student-card" onClick={open}><div className="student-card-top"><span className={`student-avatar tone-${index%4}`}>{initials(s.name)}</span><div><h3>{s.name}{demo&&<span className="fiction-label">虚构</span>}</h3><p>{s.grade||'年级未填写'}<i>·</i>{s.school||'学校未填写'}</p></div><ArrowRight size={18}/></div><div className="student-score"><div><small>最近学校成绩</small><strong>{score(s.latest_score)}<span>{s.latest_score!=null?` / ${score(s.latest_full_score)}`:' 暂无已确认成绩'}</span></strong></div><div className="mini-count"><strong>{s.exam_count||0}</strong><small>已归档试卷</small></div></div><div className="student-card-bottom">{s.pending_count?<span className="pending-text"><span/>{s.pending_count} 份试卷待校对</span>:<span className="subtle"><Check size={14}/>记录已同步</span>}<div className="tags">{(s.weak_tags||[]).slice(0,2).map(tag=><span key={tag}>{tag}</span>)}</div></div></button>}

function StudentDetail({student:s,demo,back,newExam,openExam,generate,manual,editPlan,openPractice,busy,configured}:{openPractice:()=>void;student:Student;demo:boolean;back:()=>void;newExam:()=>void;openExam:(id:string)=>void;generate:()=>void;manual:()=>void;editPlan:(p:Plan)=>void;busy:boolean;configured:boolean}){
 const exams=s.exams||[],confirmed=exams.filter(x=>x.status==='confirmed'),plans=s.plans||[];
 const last=[...confirmed].filter(x=>x.kind==='school'&&x.school_score!==null).sort((a,b)=>b.exam_date.localeCompare(a.exam_date))[0];
 return <><button className="back-link" onClick={back}><ArrowLeft size={16}/>全部学生</button><div className="profile-header"><span className="student-avatar large">{initials(s.name)}</span><div className="profile-title"><div className="title-with-badge"><h1>{s.name}</h1>{demo&&<span className="space-badge demo">虚构示例学生</span>}</div><p>{s.grade||'年级未填写'}<i>·</i>{s.school||'学校未填写'}{s.target_score!=null&&<><i>·</i>目标分数 {s.target_score}</>}</p></div><Button disabled={busy} variant="secondary" icon={<ClipboardCheck size={18}/>} onClick={openPractice}>针对性练习</Button><Button disabled={busy} icon={<FilePlus2 size={18}/>} onClick={newExam}>添加试卷</Button></div>
  {s.notes&&<div className="student-note"><PencilLine size={17}/>{s.notes}</div>}
  <div className="profile-grid"><section className="panel trend-panel"><div className="section-top"><div><h2>成绩轨迹</h2><p>只展示老师确认过的学校成绩</p></div>{last&&<div className="large-score">{last.school_score}<small>/{last.full_score}</small></div>}</div><ScoreTrend exams={confirmed}/></section><section className="panel focus-panel"><div className="section-top"><div><h2>接下来，关注这些问题</h2><p>来自已归档试卷的记录</p></div><span className="section-icon"><CircleHelp size={20}/></span></div>{s.weak_points?.length?<div className="weak-list">{s.weak_points.slice(0,5).map((w,i)=><div className="weak-item" key={`${w.tag}-${i}`}><span className="weak-number">{String(i+1).padStart(2,'0')}</span><div><strong>{w.tag}</strong><p>{(w.evidence||[]).slice(0,2).join(' · ')||'请结合原题判断具体原因'}</p></div><span className="occurrences">{w.count} 次</span></div>)}</div>:<div className="quiet-empty">归档试卷后，知识点问题会显示在这里。</div>}<div className="evidence-note"><ShieldCheck size={14}/>出现次数是观察依据，不能替代掌握度判断。</div></section></div>
  <div className="profile-grid lower"><section className="panel"><div className="section-top"><div><h2>试卷与练习 <span className="count">{exams.length}</span></h2><p>保留原始试卷与每次校对记录</p></div><Button variant="text" disabled={busy} icon={<Plus size={17}/>} onClick={newExam}>新增</Button></div>{exams.length?<div className="exam-list compact">{exams.map(x=><button className="exam-row" key={x.id} onClick={()=>openExam(x.id)}><div className="file-symbol"><FileText size={20}/></div><div className="row-main"><strong>{x.title}</strong><span>{date(x.exam_date)} · {x.kind==='school'?'学校试卷':'练习 / 复测'}</span></div><div className="exam-row-end"><Badge status={x.status}/><small>{x.school_score!=null?`${x.school_score} / ${x.full_score} 分`:'总分未录入'}</small></div></button>)}</div>:<Empty title="保存第一份试卷" text="可以上传多张照片或 PDF，也可以手工录入题目。"><Button variant="secondary" disabled={busy} onClick={newExam}>添加试卷</Button></Empty>}</section>
   <section className="panel"><div className="section-top"><div><h2>教案与跟进 <span className="count">{plans.length}</span></h2><p>让下一课和复测有据可循</p></div></div><div className="plan-actions"><Button variant="secondary" icon={<Sparkles size={16}/>} disabled={busy||!confirmed.length} onClick={generate}>{configured?'生成下一课教案':'配置模型后生成'}</Button><Button variant="text" disabled={busy} icon={<PencilLine size={16}/>} onClick={manual}>手写教案</Button></div>{!confirmed.length&&<p className="helper">AI 教案需要至少一份已确认试卷；现在可以先写手动教案。</p>}{plans.length?<div className="plan-list">{plans.map(p=><button className="plan-card" key={p.id} disabled={busy} onClick={()=>editPlan(p)}><div><span className="plan-source">{p.source==='ai'?'AI 草稿 · 可编辑':'教师教案'}</span>{p.stale&&<span className="stale-label">原卷已更新，需复核</span>}</div><h3>{p.title}</h3><p>{p.content.replace(/[#*`]/g,'').slice(0,95)}{p.content.length>95?'…':''}</p><footer><span><CalendarDays size={14}/>{p.review_date?`复测 ${date(p.review_date)}`:`创建 ${date(p.created_at)}`}</span><span>{p.review_result?'已记录复测':'打开跟进'}<ArrowRight size={14}/></span></footer></button>)}</div>:<div className="quiet-empty">还没有教案。记录目标、教学安排，再跟进课后表现。</div>}</section></div>
 </>
}
function ScoreTrend({exams}:{exams:ExamSummary[]}){
 const series=[...exams].filter(x=>x.kind==='school'&&x.school_score!==null&&x.full_score>0).sort((a,b)=>a.exam_date.localeCompare(b.exam_date)).slice(-6);
 if(!series.length)return <div className="chart-empty"><div className="empty-chart-lines"/><span>归档学校试卷后，这里会呈现成绩变化</span></div>;
 const points=series.map((x,i)=>({x:series.length===1?250:40+i*420/(series.length-1),y:150-(x.school_score!/x.full_score)*125,exam:x}));
 return <div className="score-chart"><svg viewBox="0 0 510 192" role="img" aria-label="最近学校成绩得分率趋势"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#14948a" stopOpacity=".14"/><stop offset="100%" stopColor="#14948a" stopOpacity="0"/></linearGradient></defs>{[0,50,100].map(v=><g key={v}><line x1="35" x2="480" y1={150-v*1.25} y2={150-v*1.25} stroke="#e9eff2" strokeDasharray="4 5"/><text x="3" y={154-v*1.25} fontSize="10" fill="#82909e">{v}%</text></g>)}{points.length>1&&<><path d={`M ${points[0].x},150 L ${points.map(p=>`${p.x},${p.y}`).join(' L ')} L ${points[points.length-1].x},150 Z`} fill="url(#chartFill)"/><polyline points={points.map(p=>`${p.x},${p.y}`).join(' ')} fill="none" stroke="#138e85" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></>}{points.map(p=><g key={p.exam.id}><circle cx={p.x} cy={p.y} r="5" fill="#138e85" stroke="white" strokeWidth="3"/><text textAnchor="middle" x={p.x} y={p.y-13} fill="#164c49" fontSize="12" fontWeight="600">{p.exam.school_score}/{p.exam.full_score}</text><text textAnchor="middle" x={p.x} y="178" fill="#81909b" fontSize="10">{p.exam.exam_date.slice(5).replace('-','.')}</text></g>)}</svg><div className="chart-caption"><span className="legend-dot"/>以得分率比较不同满分的试卷 · 不含 AI 建议分</div></div>
}

function ExamReview({exam,student,busy,dirty,validationTarget,configured,back,change,save,confirm,upload,recognize,generate,manual,configure}:{exam:Exam;student:Student;busy:string;dirty:boolean;validationTarget:ExamIssue|null;configured:boolean;back:()=>void;change:(e:Exam)=>void;save:()=>void;confirm:()=>void;upload:(f:FileList|File[])=>void;recognize:()=>void;generate:()=>void;manual:()=>void;configure:()=>void}){
 const [pageIndex,setPageIndex]=useState(0),[showMeta,setShowMeta]=useState(false);const fileRef=useRef<HTMLInputElement>(null);const originalRef=useRef<HTMLElement>(null);
 const pages=exam.attachments.flatMap(a=>(a.page_urls?.length?a.page_urls:[a.url]).map((url,i)=>({url,attachment:a,number:i+1})));
 const current=pages[Math.min(pageIndex,Math.max(0,pages.length-1))];
 const reviewed=exam.questions.filter(q=>q.reviewed).length,total=exam.questions.length,sum=exam.questions.reduce((n,q)=>n+(q.school_score??0),0),hasScores=exam.questions.some(q=>q.school_score!==null);
 const updateQuestion=(id:string,patch:Partial<Question>)=>change({...exam,questions:exam.questions.map(q=>q.id===id?{...q,...patch}:q)});
 const mismatch=hasScores&&exam.school_score!==null&&Math.abs(sum-exam.school_score)>.01;
 const issues=examIssues(exam),fieldError=(id:string)=>issues.find(issue=>issue.field===id)?.message||(validationTarget?.field===id?validationTarget.message:undefined);
 const moveTo=(id:string)=>{if(id.startsWith('exam-'))setShowMeta(true);focusField(id)};
 useEffect(()=>{if(validationTarget)moveTo(validationTarget.field)},[validationTarget]);
 const firstUnreviewed=exam.questions.find(q=>!q.reviewed);
 const archiveReason=!total?'添加至少一道题后，才能归档。':issues.length?issues[0].message:exam.school_score===null?(exam.kind==='school'?'学校卷归档前，请填写原卷总分。':'练习归档前，请填写老师确认总分。'):firstUnreviewed?`还有 ${total-reviewed} 道题待核对，请先核对第 ${firstUnreviewed.number} 题。`:exam.status==='confirmed'&&!dirty?'这份试卷已归档。':'所有题目已核对，可以确认归档。';
 const nextAction=!total?{label:'添加第一道题',run:()=>{const q=blankQuestion(1);change({...exam,questions:[q]});focusField(`question-${q.id}-number`)}}:issues.length?{label:'前往修正',run:()=>moveTo(issues[0].field)}:exam.school_score===null?{label:exam.kind==='school'?'填写原卷总分':'填写老师确认总分',run:()=>moveTo('exam-school-score')}:firstUnreviewed?{label:`前往第 ${firstUnreviewed.number} 题`,run:()=>moveTo(`question-${firstUnreviewed.id}-reviewed`)}:null;
 const showOriginal=(index:number)=>{setPageIndex(index);requestAnimationFrame(()=>{originalRef.current?.scrollIntoView({block:'start'});originalRef.current?.focus({preventScroll:true})})};
 return <><button className="back-link" onClick={back}><ArrowLeft size={16}/>{student.name}的档案</button><div className="review-heading"><div><div className="eyebrow">PAPER REVIEW</div><div className="title-with-badge"><h1>{exam.title}</h1><Badge status={exam.status}/></div><p>{student.name}<i>·</i>{date(exam.exam_date)}<i>·</i>{exam.kind==='school'?'学校试卷':'练习 / 复测'}<i>·</i><button className="inline-link" aria-expanded={showMeta} onClick={()=>setShowMeta(!showMeta)}>{showMeta?'收起信息':'编辑试卷信息'}</button></p></div><div className="save-state">{dirty?<><span className="unsaved-dot"/>有未保存修改</>:<><CheckCheck size={16}/>已保存</>}</div></div>
  {showMeta&&<fieldset disabled={!!busy} className="panel exam-meta"><Field label="试卷名称" error={fieldError('exam-title')}><input id="exam-title" aria-invalid={!!fieldError('exam-title')} required value={exam.title} onChange={e=>change({...exam,title:e.target.value})}/></Field><Field label="考试日期" error={fieldError('exam-date')}><input id="exam-date" aria-invalid={!!fieldError('exam-date')} required type="date" value={exam.exam_date} onChange={e=>change({...exam,exam_date:e.target.value})}/></Field><Field label="试卷类型"><select value={exam.kind} onChange={e=>change({...exam,kind:e.target.value as Exam['kind']})}><option value="school">学校试卷</option><option value="practice">练习 / 复测</option></select></Field><Field label="满分" error={fieldError('exam-full-score')}><input id="exam-full-score" aria-invalid={!!fieldError('exam-full-score')} type="number" min="0" step="any" value={visibleNumber(exam.full_score)} onChange={e=>change({...exam,full_score:numberInput(e.target.value)})}/></Field><Field label={exam.kind==='school'?'学校原始总分':'老师确认总分'} error={fieldError('exam-school-score')}><input id="exam-school-score" aria-invalid={!!fieldError('exam-school-score')} type="number" min="0" max={Number.isFinite(exam.full_score)?exam.full_score:undefined} step="any" placeholder="未知可暂留空" value={exam.school_score??''} onChange={e=>change({...exam,school_score:e.target.value===''?null:Number(e.target.value)})}/></Field><Field label="试卷备注"><input value={exam.notes} onChange={e=>change({...exam,notes:e.target.value})}/></Field></fieldset>}
  {exam.status==='confirmed'&&!dirty&&<div className="confirmed-banner"><ShieldCheck size={22}/><div><strong>这份试卷已确认归档</strong><p>修改并保存后会重新进入校对，关联教案会标记为需要复核。</p></div><Button variant="secondary" disabled={!!busy} icon={<Sparkles size={16}/>} onClick={generate}>{configured?'用这份试卷生成教案':'配置模型后生成教案'}</Button><Button variant="text" disabled={!!busy} onClick={manual}>手写教案</Button></div>}
  <div className="review-layout"><section className="original-panel" ref={originalRef} tabIndex={-1} aria-label="试卷原件"><div className="original-toolbar"><div><FileText size={18}/><strong>试卷原件</strong><span>{pages.length} 页</span></div><button className="icon-button" aria-label="添加试卷原件" onClick={()=>fileRef.current?.click()} disabled={!!busy}><Plus size={19}/></button></div><input hidden ref={fileRef} type="file" accept=".jpg,.jpeg,.png,.webp,.pdf" multiple onChange={e=>{if(e.target.files)upload(e.target.files);e.target.value=''}}/>
   {current?<><div className="original-view">{current.attachment.mime==='application/pdf'&&current.url===current.attachment.url?<iframe title="试卷 PDF 原件" src={current.url}/>:<a href={current.url} target="_blank" rel="noreferrer" title="打开原图查看细节"><img src={current.url} alt={`${current.attachment.filename} 第 ${current.number} 页`}/></a>}</div><div className="page-controls"><button className="icon-button" aria-label="上一页" disabled={pageIndex<=0} onClick={()=>setPageIndex(v=>v-1)}><ChevronLeft size={19}/></button><span>{Math.min(pageIndex+1,pages.length)} / {pages.length}</span><button className="icon-button" aria-label="下一页" disabled={pageIndex>=pages.length-1} onClick={()=>setPageIndex(v=>v+1)}><ChevronRight size={19}/></button><a className="original-link" href={current.attachment.url} target="_blank" rel="noreferrer"><ExternalLink size={14}/>原始文件</a></div><div className="attachment-name">{current.attachment.filename}</div></>:<button className="upload-surface" onClick={()=>fileRef.current?.click()} disabled={!!busy}><UploadCloud size={34}/><strong>添加试卷照片或 PDF</strong><span>支持多张图片、PDF<br/>最多 8 个文件，每个不超过 20 MB</span><span className="upload-faux-button">选择文件</span></button>}
   <div className="original-bottom"><ShieldCheck size={15}/><span>原件在本机保存。点击「识别题目」才调用模型。</span></div>
  </section>
  <section className="questions-panel"><div className="questions-toolbar"><div><h2>逐题校对 <span className="count">{total}</span></h2><p>对照原卷，确认答案、得分和错因。</p></div><Button variant="secondary" icon={busy==='recognize'?<LoaderCircle size={16} className="spin"/>:<Sparkles size={16}/>} disabled={!!busy||!pages.length||exam.status==='confirmed'} onClick={configured?recognize:configure}>{busy==='recognize'?'正在识别':configured?'识别题目':'配置模型后识别'}</Button></div>
   {!configured&&<div className="inline-hint"><CircleHelp size={16}/><span>尚未连接模型。可手工添加题目，或<button className="inline-link" onClick={configure}>前往配置</button>。</span></div>}
   <div className="review-progress"><span>已确认 {reviewed} / {total} 题</span><div><span style={{width:`${total?reviewed/total*100:0}%`}}/></div></div>
   <div className="question-stack">{exam.questions.map((q,index)=>{const sourceIndex=pages.findIndex(p=>Boolean(p.url)&&(!q.source_attachment_id||p.attachment.id===q.source_attachment_id)&&p.number===q.source_page);return <QuestionEditor librarySource={exam.question_sources?.[q.id]} scoreLabel={exam.kind==='school'?'学校原始得分':'老师确认得分'} key={q.id} question={q} index={index} disabled={!!busy} update={patch=>updateQuestion(q.id,patch)} remove={()=>{if(window.confirm(`删除第 ${q.number} 题？保存前可以离开页面放弃修改。`))change({...exam,questions:exam.questions.filter(item=>item.id!==q.id)})}} issues={issues} viewSource={sourceIndex>=0?()=>showOriginal(sourceIndex):undefined}/>})}{!total&&<div className="question-empty"><ClipboardCheck size={34}/><h3>校对从第一道题开始</h3><p>上传后识别题目，或直接手工录入。<br/>识别结果只有经你确认，才会进入学生档案。</p></div>}<Button variant="add-question" icon={<Plus size={18}/>} disabled={!!busy} onClick={()=>{const q=blankQuestion(total+1);change({...exam,questions:[...exam.questions,q]});focusField(`question-${q.id}-number`)}}>手工添加一道题</Button></div>
  </section></div>
  <div className="review-dock"><div className="dock-info"><div><strong>{exam.kind==='school'?'原卷总分':'老师确认总分'} <span>{score(exam.school_score)}</span><small> / {Number.isFinite(exam.full_score)?exam.full_score:'—'}</small></strong><button className="inline-link" disabled={!!busy} onClick={()=>moveTo('exam-school-score')}>修改总分</button></div><p id="archive-guidance" className="archive-guidance" aria-live="polite">{archiveReason}{nextAction&&<button className="inline-link" disabled={!!busy} onClick={nextAction.run}>{nextAction.label}<ArrowRight size={13}/></button>}</p>{mismatch&&<p className="score-reconciliation">已录得分合计 {sum}；可只录重点题，请核对与{exam.kind==='school'?'原卷总分':'老师确认总分'}的差异。</p>}</div><div className="dock-buttons"><Button variant="secondary" icon={<Save size={17}/>} onClick={save} disabled={!!busy||!dirty}>{busy==='save'?'正在保存':'保存修改'}</Button><Button icon={<CheckCheck size={17}/>} onClick={confirm} aria-describedby="archive-guidance" disabled={!!busy||issues.length>0||!total||reviewed!==total||exam.school_score===null||(exam.status==='confirmed'&&!dirty)}>{busy==='confirm'?'正在归档':exam.status==='confirmed'&&!dirty?'已确认归档':'确认并归档'}</Button></div></div>
 </>
}

function QuestionEditor({question:q,index,update,remove,viewSource,librarySource,disabled,scoreLabel,issues}:{issues:ExamIssue[];scoreLabel:string;question:Question;index:number;update:(p:Partial<Question>)=>void;remove:()=>void;viewSource?:()=>void;librarySource?:QuestionSource;disabled:boolean}){
 const change=(patch:Partial<Question>)=>update({...patch,reviewed:false,needs_review:true});
 const fieldError=(suffix:string)=>issues.find(issue=>issue.field===`question-${q.id}-${suffix}`)?.message;
 return <article id={`question-${q.id}`} className={`question-card ${q.reviewed?'reviewed':''}`}><div className="question-header"><div className="question-index">{String(index+1).padStart(2,'0')}</div><label className="question-number">题号<input id={`question-${q.id}-number`} aria-invalid={!!fieldError('number')} title={fieldError('number')} aria-label={`第${index+1}题题号`} value={q.number} onChange={e=>change({number:e.target.value})} disabled={disabled}/></label>{q.reviewed?<span className="question-confirmed"><Check size={14}/>已核对</span>:<span className="question-unconfirmed">待确认</span>}<button className="icon-button danger-icon" aria-label={`删除第${q.number}题`} onClick={remove} disabled={disabled}><Trash2 size={16}/></button></div>{fieldError('number')&&<p className="field-error question-error" role="alert">{fieldError('number')}</p>}<Field label="题干"><textarea rows={2} value={q.stem} placeholder="填写原题，也可只录需要分析的重点题" onChange={e=>change({stem:e.target.value})} disabled={disabled}/></Field><div className="form-grid"><Field label="学生答案"><textarea rows={2} value={q.student_answer} placeholder="保留原始答案" onChange={e=>change({student_answer:e.target.value})} disabled={disabled}/></Field><Field label="正确答案"><textarea rows={2} value={q.correct_answer} placeholder="需由老师核对" onChange={e=>change({correct_answer:e.target.value})} disabled={disabled}/></Field></div><div className="score-fields"><Field label={scoreLabel} error={fieldError('score')}><input id={`question-${q.id}-score`} aria-invalid={!!fieldError('score')} aria-label={`第${q.number}题得分`} type="number" min="0" max={Number.isFinite(q.max_score)?q.max_score:undefined} step="any" value={q.school_score??''} onChange={e=>change({school_score:e.target.value===''?null:Number(e.target.value)})} disabled={disabled}/></Field><span className="score-slash">/</span><Field label="本题满分" error={fieldError('max')}><input id={`question-${q.id}-max`} aria-invalid={!!fieldError('max')} aria-label={`第${q.number}题满分`} type="number" min="0" step="any" value={visibleNumber(q.max_score)} onChange={e=>change({max_score:numberInput(e.target.value),ai_score:q.ai_score!==null&&q.ai_score>Number(e.target.value)?null:q.ai_score})} disabled={disabled}/></Field><div className="ai-suggestion"><span>AI 建议分</span><strong>{score(q.ai_score)}</strong><small>仅供参考{q.ai_score!==null&&<> · <button type="button" className="inline-link" disabled={disabled} onClick={()=>change({ai_score:null})}>清除建议</button></>}</small></div></div><div className="form-grid"><Field label="知识点"><input value={q.knowledge_tag} placeholder="如：一般过去时" onChange={e=>change({knowledge_tag:e.target.value})} disabled={disabled}/></Field><Field label="问题 / 可能原因"><input value={q.error_reason} placeholder="区分已观察与推测" onChange={e=>change({error_reason:e.target.value})} disabled={disabled}/></Field></div><Field label="教师备注"><input value={q.teacher_note} placeholder="保留你的教学判断" onChange={e=>change({teacher_note:e.target.value})} disabled={disabled}/></Field><footer className="question-footer">{librarySource?.url&&<a className="inline-link" href={librarySource.url} target="_blank" rel="noreferrer" title={librarySource.document_title}><FileText size={14}/>查看题库原文第 {librarySource.source_page} 页</a>}{!librarySource?.url&&viewSource&&<button className="inline-link" onClick={viewSource} disabled={disabled}><FileText size={14}/>查看来源第 {q.source_page||1} 页</button>}<label className="check-label"><input id={`question-${q.id}-reviewed`} type="checkbox" checked={q.reviewed} onChange={e=>update({reviewed:e.target.checked,needs_review:!e.target.checked})} disabled={disabled}/><span>已对照原卷核对</span></label></footer></article>
}

function StudentForm({demo,close,submit}:{demo:boolean;close:()=>void;submit:(v:unknown)=>Promise<void>}){
 const [busy,setBusy]=useState(false),[error,setError]=useState(''),[modified,setModified]=useState(false);
 const closing=useProtectedClose(modified,busy,'学生档案',close);
 async function handle(e:FormEvent<HTMLFormElement>){
  e.preventDefault();if(busy)return;const form=new FormData(e.currentTarget),name=String(form.get('name')||'').trim();
  if(!name){setError('请填写学生姓名，不能只输入空格。');focusField('new-student-name');return}
  setBusy(true);setError('');try{await submit({name,grade:String(form.get('grade')||'').trim(),school:String(form.get('school')||'').trim(),notes:String(form.get('notes')||''),target_score:form.get('target_score')===''?null:Number(form.get('target_score'))});setModified(false)}catch(err){setError(errorText(err))}finally{setBusy(false)}
 }
 return <Modal title="添加学生" kicker="A NEW LEARNING JOURNEY" onClose={closing} busy={busy}>
  <form onSubmit={handle} onChange={()=>setModified(true)} className="modal-body">
   <fieldset disabled={busy} className="form-fieldset">
    {demo&&<div className="alert info"><Sparkles size={18}/><span>你正在示例空间添加虚构学生。真实资料请保存到个人资料库。</span></div>}
    {error&&<div className="alert error" role="alert">{error}</div>}
    <div className="form-grid">
     <Field label="学生姓名 *"><input id="new-student-name" name="name" required maxLength={80} placeholder="例如：小林" autoFocus/></Field>
     <Field label="年级"><input name="grade" placeholder="例如：七年级"/></Field>
     <Field label="学校"><input name="school" placeholder="可选"/></Field>
     <Field label="目标分数"><input name="target_score" type="number" min="0" step="any" placeholder="可选"/></Field>
    </div>
    <Field label="教学备注"><textarea rows={3} name="notes" placeholder="记录教材版本、学习目标和需要留意的情况。"/></Field>
    <p className="helper">学生仅作为教学档案保存，不需要注册或登录。</p>
    <div className="modal-footer"><span className="helper">{modified?'尚未保存':''}</span><Button type="button" variant="secondary" onClick={closing} disabled={busy}>取消</Button><Button type="submit" disabled={busy} icon={busy?<LoaderCircle className="spin" size={17}/>:<Plus size={17}/>}>{busy?'正在创建':'创建学生档案'}</Button></div>
   </fieldset>
  </form>
 </Modal>
}
function ExamForm({name,close,submit}:{name:string;close:()=>void;submit:(v:unknown,files:File[])=>Promise<void>}){
 const [busy,setBusy]=useState(false),[error,setError]=useState(''),[files,setFiles]=useState<File[]>([]),[kind,setKind]=useState('school'),[modified,setModified]=useState(false),[fullScore,setFullScore]=useState('100'),[schoolScore,setSchoolScore]=useState('');
 const closing=useProtectedClose(modified,busy,'这份试卷',close);
 const fullScoreError=fullScore!==''&&Number(fullScore)>0?'':'请填写大于 0 的试卷满分。';
 const scoreError=schoolScore!==''&&(Number(schoolScore)<0||Number(schoolScore)>Number(fullScore))?'总分须在 0 与试卷满分之间。':'';
 async function handle(e:FormEvent<HTMLFormElement>){
  e.preventDefault();if(busy)return;const form=new FormData(e.currentTarget),title=String(form.get('title')||'').trim();
  if(!title){setError('请填写试卷名称，不能只输入空格。');focusField('new-exam-title');return}
  if(fullScoreError||scoreError){setError(fullScoreError||scoreError);focusField(fullScoreError?'new-exam-full-score':'new-exam-school-score');return}
  setBusy(true);setError('');try{await submit({title,exam_date:form.get('exam_date'),kind,full_score:Number(fullScore),school_score:schoolScore===''?null:Number(schoolScore),notes:form.get('notes')||''},files);setModified(false)}catch(err){setError(errorText(err))}finally{setBusy(false)}
 }
 return <Modal title={`为${name}添加试卷`} kicker="KEEP THE EVIDENCE" onClose={closing} busy={busy}>
  <form onSubmit={handle} onChange={()=>setModified(true)} className="modal-body"><fieldset disabled={busy} className="form-fieldset">
   {error&&<div className="alert error" role="alert">{error}</div>}
   <Field label="试卷名称 *"><input id="new-exam-title" name="title" required placeholder="例如：七年级英语十月月考" autoFocus/></Field>
   <div className="form-grid">
    <Field label="考试日期 *"><input name="exam_date" type="date" defaultValue={today()} required/></Field>
    <Field label="记录类型"><select value={kind} onChange={e=>setKind(e.target.value)}><option value="school">学校试卷</option><option value="practice">课堂练习 / 复测</option></select></Field>
    <Field label="试卷满分 *" error={fullScoreError}><input id="new-exam-full-score" aria-invalid={!!fullScoreError} name="full_score" type="number" min="0" step="any" value={fullScore} onChange={e=>setFullScore(e.target.value)} required/></Field>
    <Field label={kind==='school'?'学校原始总分':'老师确认总分'} error={scoreError} hint="未知可留空，归档前再补充"><input id="new-exam-school-score" aria-invalid={!!scoreError} name="school_score" type="number" min="0" max={Number(fullScore)>0?Number(fullScore):undefined} step="any" value={schoolScore} onChange={e=>setSchoolScore(e.target.value)} placeholder="未知可稍后补充"/></Field>
   </div>
   <label className="modal-file-upload"><UploadCloud size={28}/><strong>{files.length?`已选择 ${files.length} 个文件 · 点击重新选择`:'选择试卷照片或 PDF'}</strong><span>最多 8 个文件 · 20 MB / 文件 · 也可稍后上传</span><input aria-label="选择试卷照片或 PDF" type="file" accept=".jpg,.jpeg,.png,.webp,.pdf" multiple onChange={e=>{const picked=Array.from(e.target.files||[]);e.target.value='';if(!picked.length)return;if(picked.length>8){setError('一次最多上传 8 个文件，已保留上次选择。');return}if(picked.some(f=>f.size>20*1024*1024)){setError('每个文件不能超过 20 MB，已保留上次选择。');return}setError('');setFiles(picked);setModified(true)}}/></label>
   {files.length>0&&<ul className="file-list">{files.map((f,i)=><li key={`${f.name}-${i}`}><FileText size={15}/><span>{f.name}</span><button type="button" className="icon-button" aria-label={`移除${f.name}`} onClick={()=>{setFiles(files.filter((_,n)=>n!==i));setModified(true)}}><X size={15}/></button></li>)}</ul>}
   <Field label="备注"><input name="notes" placeholder="例如：只录入阅读理解与作文部分"/></Field>
   <p className="helper"><ShieldCheck size={14}/>上传只保存原件，不会自动将照片发送给 AI。</p>
   <div className="modal-footer"><span className="helper">{modified?'尚未保存':''}</span><Button type="button" variant="secondary" onClick={closing} disabled={busy}>取消</Button><Button type="submit" disabled={busy} icon={busy?<LoaderCircle className="spin" size={17}/>:<ArrowRight size={17}/>}>{busy?'正在保存试卷':'创建并开始校对'}</Button></div>
  </fieldset></form>
 </Modal>
}

function SettingsModal({workspace,close,saved}:{workspace:Workspace;close:()=>void;saved:()=>void}){
 const [settings,setSettings]=useState<Settings|null>(null),[key,setKey]=useState(''),[clearKey,setClearKey]=useState(false),[busy,setBusy]=useState(''),[error,setError]=useState(''),[message,setMessage]=useState(''),[loading,setLoading]=useState(true);
 const initialSettings=useRef('');
 const settingsKey=(value:Settings)=>JSON.stringify([value.base_url,value.model,value.vision_model]);
 const changed=!!settings&&(settingsKey(settings)!==initialSettings.current||key!==''||clearKey);
 const closing=useProtectedClose(changed,!!busy,'模型配置',close);
 async function load(){setLoading(true);setError('');try{const result=await request<Settings>(workspace,'/settings');initialSettings.current=settingsKey(result);setSettings(result)}catch(e){setError(errorText(e))}finally{setLoading(false)}}
 useEffect(()=>{void load()},[workspace]);
 const update=(patch:Partial<Settings>)=>{if(settings)setSettings({...settings,...patch});setMessage('')};
 async function save(){
  if(!settings||busy||!changed)return;
  if(!settings.base_url.trim()||!settings.model.trim()||!settings.vision_model.trim()){setError('请填写服务地址、文字模型和视觉模型名称。');focusField(!settings.base_url.trim()?'model-base-url':!settings.model.trim()?'model-text-name':'model-vision-name');return}
  setBusy('save');setError('');setMessage('');
  try{const result=await request<Settings>(workspace,'/settings',json('PUT',{base_url:settings.base_url.trim(),model:settings.model.trim(),vision_model:settings.vision_model.trim(),api_key:key,clear_api_key:clearKey}));initialSettings.current=settingsKey(result);setSettings(result);setKey('');setClearKey(false);setMessage('模型配置已保存。测试连接只验证文字模型，识别题目时才会使用视觉模型。');saved()}catch(e){setError(errorText(e))}finally{setBusy('')}
 }
 async function test(){if(busy||changed||!settings?.has_api_key)return;setBusy('test');setError('');setMessage('');try{const result=await request<{ok:boolean;message:string}>(workspace,'/settings/test',json('POST',{}));if(result.ok)setMessage(result.message+'（本次只验证文字模型连接。）');else setError(result.message)}catch(e){setError(errorText(e))}finally{setBusy('')}}
 const testReason=changed?'有未保存的配置，请先保存后再测试。':!settings?.has_api_key?'请填写并保存 API 密钥，再测试连接。':'测试仅发送连接检查，不发送学生资料。';
 return <Modal title="模型连接设置" kicker="当前老师 · 两个空间共用模型配置" onClose={closing} busy={!!busy}>
  <form className="modal-body" onSubmit={e=>{e.preventDefault();void save()}}>
   {error&&<div className="alert error" role="alert"><AlertCircle size={18}/><span>{error}</span></div>}
   {message&&<div className="alert success" role="status"><CheckCheck size={18}/><span>{message}</span></div>}
   {loading?<div className="page-loading"><LoaderCircle className="spin" size={24}/><p>正在读取配置…</p></div>:settings?<fieldset disabled={!!busy} className="form-fieldset">
    <div className="alert info"><Sparkles size={18}/><span>已为 DeepSeek 准备好模型预设，只需填写 API Key。兼容其他服务时可修改地址与模型。</span></div>
    <div className="privacy-note"><ShieldCheck size={22}/><p>密钥只保存在本机服务端，不会在界面回显。识别试卷、解析教材或生成教案与练习时，才会把对应资料发送到你配置的服务。</p></div>
    <Field label="服务地址" hint="兼容 OpenAI 接口；使用 HTTPS，只有本机服务可用 HTTP"><input id="model-base-url" required type="url" value={settings.base_url} placeholder="https://api.deepseek.com" onChange={e=>update({base_url:e.target.value})}/></Field>
    <div className="form-grid">
     <Field label="文字模型名称"><input id="model-text-name" required value={settings.model} placeholder="填写服务提供方的模型 ID" onChange={e=>update({model:e.target.value})}/></Field>
     <Field label="视觉模型名称"><input id="model-vision-name" required value={settings.vision_model} placeholder="填写支持图片的模型 ID" onChange={e=>update({vision_model:e.target.value})}/></Field>
    </div>
    <Field label={`API 密钥${settings.has_api_key?' · 已保存':''}`} hint="留空将保留已有密钥。不要将密钥写进学生资料或备注。"><input type="password" autoComplete="new-password" value={key} placeholder={settings.has_api_key?'已保存，输入可替换':'粘贴 API 密钥'} onChange={e=>{setKey(e.target.value);setClearKey(false);setMessage('')}}/></Field>
    {settings.has_api_key&&<label className="check-label"><input type="checkbox" checked={clearKey} onChange={e=>{setClearKey(e.target.checked);if(e.target.checked)setKey('');setMessage('')}}/>删除已保存的密钥</label>}
    <p className="helper" id="connection-test-help">{testReason}</p>
    <div className="modal-footer settings-footer">
     <Button type="button" variant="secondary" onClick={test} disabled={!!busy||changed||!settings.has_api_key} aria-describedby="connection-test-help" icon={busy==='test'?<LoaderCircle size={16} className="spin"/>:<RefreshCw size={16}/>}>{busy==='test'?'正在测试':'测试已保存的连接'}</Button>
     <Button type="submit" disabled={!!busy||!changed} icon={busy==='save'?<LoaderCircle size={16} className="spin"/>:<Save size={16}/>}>{busy==='save'?'正在保存':changed?'保存配置':'配置未修改'}</Button>
    </div>
   </fieldset>:<Empty title="未能读取模型配置" text="请确认本地服务仍在运行，然后重新读取。"><Button type="button" icon={<RefreshCw size={17}/>} onClick={()=>void load()}>重新读取</Button></Empty>}
  </form>
 </Modal>
}

function PlanEditor({plan,student,examId,close,save}:{plan:Plan|null;student:Student;examId?:string;close:()=>void;save:(v:unknown)=>Promise<void>}){
 const [title,setTitle]=useState(plan?.title||`${student.name}的下一课教案`),[content,setContent]=useState(plan?.content||''),[lessonNote,setLessonNote]=useState(plan?.lesson_note||''),[reviewDate,setReviewDate]=useState(plan?.review_date||''),[reviewResult,setReviewResult]=useState(plan?.review_result||''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[modified,setModified]=useState(false);
 const closing=useProtectedClose(modified,busy,'教案',close);
 async function handle(e:FormEvent){e.preventDefault();if(busy||(plan&&!modified))return;if(!title.trim()||!content.trim()){setError('请填写教案标题与教学安排，不能只输入空格。');focusField(!title.trim()?'plan-title':'plan-content');return}setBusy(true);setError('');try{await save({title:title.trim(),content,lesson_note:lessonNote,review_date:reviewDate||null,review_result:reviewResult,...(!plan?{exam_id:examId||null}:{})});setModified(false)}catch(err){setError(errorText(err))}finally{setBusy(false)}}
 return <Modal title={plan?'教案与课后跟进':'写一份教学计划'} kicker={`${student.name} · ${plan?.source==='ai'?'AI 生成，可由老师调整':'教师记录'}`} onClose={closing} busy={busy} wide><form onSubmit={handle} className="modal-body"><fieldset disabled={busy} className="form-fieldset">{error&&<div className="alert error">{error}</div>}{plan?.stale&&<div className="alert warning"><AlertCircle size={18}/><span>关联试卷已经修改。这份教案依据的是旧版本，请回看原卷并重新生成或调整。</span></div>}<Field label="教案标题"><input id="plan-title" required value={title} onChange={e=>{setTitle(e.target.value);setModified(true)}}/></Field><Field label="教学安排" hint="可以记录课堂目标、原题依据、教学活动和检查方式"><textarea id="plan-content" className="plan-content" rows={13} required value={content} placeholder={'本课目标\n\n0–5 分钟：回顾与诊断\n5–20 分钟：重点讲解\n20–35 分钟：变式练习\n35–45 分钟：独立检查与总结\n\n原题依据与后续复测'} onChange={e=>{setContent(e.target.value);setModified(true)}}/></Field><div className="followup-divider"><span>教完之后，再留下一条证据</span></div><Field label="课后记录"><textarea rows={3} value={lessonNote} placeholder="实际讲了什么？学生能否独立完成？哪些判断需要修正？" onChange={e=>{setLessonNote(e.target.value);setModified(true)}}/></Field><div className="form-grid"><Field label="复测日期"><input type="date" value={reviewDate} onChange={e=>{setReviewDate(e.target.value);setModified(true)}}/></Field><Field label="复测结果"><textarea rows={2} value={reviewResult} placeholder="填写实际观察结果；后续试卷可另建为练习 / 复测" onChange={e=>{setReviewResult(e.target.value);setModified(true)}}/></Field></div><div className="modal-footer"><span className="helper" role="status">{modified?'有未保存修改':plan?'已保存':'尚未保存'}</span><Button variant="secondary" type="button" onClick={closing}>关闭</Button><Button type="submit" disabled={busy||!!plan&&!modified} icon={busy?<LoaderCircle size={17} className="spin"/>:<Save size={17}/>}>{busy?'正在保存':'保存教案与跟进'}</Button></div></fieldset></form></Modal>
}
